/*
 * High-performance portfolio calculations using C extension
 *
 * Implements:
 *   portfolio risk   = sqrt(x^T * S * x)
 *   portfolio return = x^T * r
 *
 * Design notes:
 *   - NumPy arrays that are already C-contiguous float64 are used with no copy.
 *   - Plain Python sequences (lists/tuples of lists) are converted with a tight
 *     C loop instead of numpy's generic nested-sequence machinery, which is
 *     several times faster and matters because the conversion is O(n^2).
 *   - The actual math is done on contiguous double buffers, where the compiler
 *     can vectorize the inner dot products.  All terms are accumulated in
 *     double precision, so results agree with the pure Python baseline far
 *     inside the required 1e-10 tolerance.
 */

#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>

/* ------------------------------------------------------------------ */
/* Fast conversion helpers                                             */
/* ------------------------------------------------------------------ */

/*
 * Copy `count` numbers from a Python sequence into `buf`.
 * Returns 0 on success, -1 with an exception set on failure.
 *
 * The hot path (a list of Python floats) uses PyList fast macros and
 * PyFloat_AS_DOUBLE, avoiding the per-item call overhead of
 * PyFloat_AsDouble / numpy's generic sequence conversion.
 */
static int fill_doubles(PyObject *seq, double *buf, Py_ssize_t count) {
    PyObject *fast;
    int borrowed = 0;

    if (PyList_CheckExact(seq) || PyTuple_CheckExact(seq)) {
        fast = seq;
        borrowed = 1;
    } else {
        fast = PySequence_Fast(seq, "expected a sequence of numbers");
        if (fast == NULL)
            return -1;
    }

    if (PySequence_Fast_GET_SIZE(fast) != count) {
        PyErr_SetString(PyExc_ValueError,
                        "inconsistent sequence dimensions");
        if (!borrowed)
            Py_DECREF(fast);
        return -1;
    }

    for (Py_ssize_t i = 0; i < count; i++) {
        PyObject *item = PySequence_Fast_GET_ITEM(fast, i);
        if (PyFloat_CheckExact(item)) {
            buf[i] = PyFloat_AS_DOUBLE(item);
        } else if (PyLong_Check(item)) {
            buf[i] = PyLong_AsDouble(item);
            if (buf[i] == -1.0 && PyErr_Occurred()) {
                if (!borrowed)
                    Py_DECREF(fast);
                return -1;
            }
        } else {
            buf[i] = PyFloat_AsDouble(item);
            if (buf[i] == -1.0 && PyErr_Occurred()) {
                if (!borrowed)
                    Py_DECREF(fast);
                return -1;
            }
        }
    }

    if (!borrowed)
        Py_DECREF(fast);
    return 0;
}

/*
 * Obtain a 1-D contiguous float64 array from `obj`.
 * Returns a new reference (owned by the caller) or NULL with an exception.
 */
static PyArrayObject *as_double_1d(PyObject *obj, npy_intp *n_out) {
    if (PyArray_Check(obj)) {
        PyArrayObject *a = (PyArrayObject *)PyArray_FROM_OTF(
            obj, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
        if (a == NULL)
            return NULL;
        if (PyArray_NDIM(a) != 1) {
            PyErr_SetString(PyExc_ValueError,
                            "expected a 1-D array of weights/returns");
            Py_DECREF(a);
            return NULL;
        }
        *n_out = PyArray_DIM(a, 0);
        return a;
    }

    Py_ssize_t n = PySequence_Size(obj);
    if (n < 0)
        return NULL;

    npy_intp dims[1] = {(npy_intp)n};
    PyArrayObject *a = (PyArrayObject *)PyArray_SimpleNew(1, dims, NPY_DOUBLE);
    if (a == NULL)
        return NULL;

    if (n > 0 && fill_doubles(obj, (double *)PyArray_DATA(a), n) < 0) {
        Py_DECREF(a);
        return NULL;
    }

    *n_out = (npy_intp)n;
    return a;
}

/*
 * Obtain a square 2-D contiguous float64 array from `obj`.
 * Returns a new reference (owned by the caller) or NULL with an exception.
 */
static PyArrayObject *as_double_2d(PyObject *obj, npy_intp *n_out) {
    if (PyArray_Check(obj)) {
        PyArrayObject *a = (PyArrayObject *)PyArray_FROM_OTF(
            obj, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
        if (a == NULL)
            return NULL;
        if (PyArray_NDIM(a) != 2 || PyArray_DIM(a, 0) != PyArray_DIM(a, 1)) {
            PyErr_SetString(PyExc_ValueError,
                            "expected a square 2-D covariance matrix");
            Py_DECREF(a);
            return NULL;
        }
        *n_out = PyArray_DIM(a, 0);
        return a;
    }

    PyObject *outer = PySequence_Fast(obj, "expected a sequence of rows");
    if (outer == NULL)
        return NULL;

    Py_ssize_t n = PySequence_Fast_GET_SIZE(outer);
    npy_intp dims[2] = {(npy_intp)n, (npy_intp)n};

    PyArrayObject *a = (PyArrayObject *)PyArray_SimpleNew(2, dims, NPY_DOUBLE);
    if (a == NULL) {
        Py_DECREF(outer);
        return NULL;
    }

    double *data = (double *)PyArray_DATA(a);
    for (Py_ssize_t i = 0; i < n; i++) {
        PyObject *row = PySequence_Fast_GET_ITEM(outer, i);
        if (fill_doubles(row, data + i * n, n) < 0) {
            Py_DECREF(outer);
            Py_DECREF(a);
            return NULL;
        }
    }

    Py_DECREF(outer);
    *n_out = (npy_intp)n;
    return a;
}

/* ------------------------------------------------------------------ */
/* Portfolio calculations                                              */
/* ------------------------------------------------------------------ */

static PyObject *portfolio_risk_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *cov_obj;
    PyArrayObject *weights_array = NULL, *cov_array = NULL;
    npy_intp n = 0, nc = 0;
    double risk_squared = 0.0;

    (void)self;

    /* Accept any Python objects here; conversion happens in the helpers. */
    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &cov_obj))
        return NULL;

    weights_array = as_double_1d(weights_obj, &n);
    if (weights_array == NULL)
        return NULL;

    cov_array = as_double_2d(cov_obj, &nc);
    if (cov_array == NULL) {
        Py_DECREF(weights_array);
        return NULL;
    }

    if (n != nc) {
        PyErr_SetString(PyExc_ValueError,
                        "weights and covariance matrix dimensions do not match");
        Py_DECREF(weights_array);
        Py_DECREF(cov_array);
        return NULL;
    }

    {
        const double *restrict x = (const double *)PyArray_DATA(weights_array);
        const double *restrict S = (const double *)PyArray_DATA(cov_array);

        /*
         * risk^2 = sum_i x[i] * (sum_j S[i][j] * x[j])
         *
         * This mirrors the baseline expression exactly (S*x followed by
         * x^T*(S*x)), and keeps each row dot product in a contiguous buffer.
         */
        Py_BEGIN_ALLOW_THREADS
        for (npy_intp i = 0; i < n; i++) {
            const double *restrict row = S + i * n;
            double row_sum = 0.0;

            for (npy_intp j = 0; j < n; j++)
                row_sum += row[j] * x[j];

            risk_squared += x[i] * row_sum;
        }
        Py_END_ALLOW_THREADS
    }

    Py_DECREF(weights_array);
    Py_DECREF(cov_array);

    return PyFloat_FromDouble(sqrt(risk_squared));
}

static PyObject *portfolio_return_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *returns_obj;
    PyArrayObject *weights_array = NULL, *returns_array = NULL;
    npy_intp n = 0, nr = 0;
    double total_return = 0.0;

    (void)self;

    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &returns_obj))
        return NULL;

    weights_array = as_double_1d(weights_obj, &n);
    if (weights_array == NULL)
        return NULL;

    returns_array = as_double_1d(returns_obj, &nr);
    if (returns_array == NULL) {
        Py_DECREF(weights_array);
        return NULL;
    }

    if (n != nr) {
        PyErr_SetString(PyExc_ValueError,
                        "weights and expected returns dimensions do not match");
        Py_DECREF(weights_array);
        Py_DECREF(returns_array);
        return NULL;
    }

    {
        const double *restrict x = (const double *)PyArray_DATA(weights_array);
        const double *restrict r = (const double *)PyArray_DATA(returns_array);

        Py_BEGIN_ALLOW_THREADS
        for (npy_intp i = 0; i < n; i++)
            total_return += x[i] * r[i];
        Py_END_ALLOW_THREADS
    }

    Py_DECREF(weights_array);
    Py_DECREF(returns_array);

    return PyFloat_FromDouble(total_return);
}

static PyMethodDef module_methods[] = {
    {"portfolio_risk_c", portfolio_risk_c, METH_VARARGS, "Calculate portfolio risk"},
    {"portfolio_return_c", portfolio_return_c, METH_VARARGS, "Calculate portfolio return"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT,
    "portfolio_optimized_c",
    "Optimized portfolio calculations",
    -1,
    module_methods
};

PyMODINIT_FUNC PyInit_portfolio_optimized_c(void) {
    import_array();  /* Initialize NumPy C API */
    return PyModule_Create(&moduledef);
}
